        bytes32 itemTypeHash,
        bytes32 hookTypeHash,
        bytes32 rentalOrderTypeHash,
        bytes32 orderFulfillmentTypeHash,
        bytes32 orderMetadataTypeHash,
        bytes32 rentPayloadTypeHash
    )
{
