import {BaseTestWithoutEngine} from "@test/BaseTest.sol";
import {PaymentEscrow} from "@src/modules/PaymentEscrow.sol";
import {toKeycode, toRole} from "@src/libraries/KernelUtils.sol";

contract Policy_Test is BaseTestWithoutEngine {
    function test_revertingPolicy_behavior () public {
        vm.startPrank(deployer.addr);

        BadPolicy policy = new BadPolicy();
        // Activate policy
        kernel.executeAction(Actions.ActivatePolicy, address(policy));

        // @ -> deactivation of this policy will not work
        vm.expectRevert(abi.encodeWithSelector(Errors.Kernel_PolicyNotApproved.selector, address(policy)));
        kernel.executeAction(Actions.DeactivatePolicy, address(policy));

        // test already installed module upgrade
        assert(address(kernel.getModuleForKeycode(ESCRW.KEYCODE())) != address(0x0));

        PaymentEscrow pe = new PaymentEscrow(kernel);
        assertEq(Keycode.unwrap(ESCRW.KEYCODE()), Keycode.unwrap(pe.KEYCODE()));

        // @-> module upgradeability is blocked
        vm.expectRevert(bytes("stop process"));
        kernel.executeAction(Actions.UpgradeModule, address(pe));
        vm.stopPrank();
    }
}

contract BadPolicy {
    bool public isActive;
    uint256 _counter;
    function setActiveStatus(bool activate_) external {
        // @ -> ignore so isActive stays false ..and revert on deactivation
